using System;using System.Reflection;using Exoduser.UnityPort.Core;
class DruidRigTests {
 static int checks,bad;static void Check(bool ok,string name){checks++;if(!ok){bad++;Console.WriteLine("FAIL "+name);}}
 static int Main(){var t=Assembly.GetExecutingAssembly().GetType("Exoduser.UnityPort.NativeDruidRigPolicy");Check(t!=null,"boss rig-pixel opt-in and state policy exists");if(t!=null){var requested=t.GetMethod("Requested");Func<string[],bool> on=a=>(bool)requested.Invoke(null,new object[]{a});Check(!on(null),"null args default off");Check(!on(new string[0]),"default off");Check(on(new[]{"--boss-render=rigpixel"}),"explicit equal option");Check(on(new[]{"--boss-render","rigpixel"}),"explicit separate option");Check(!on(new[]{"--boss-render=rigpixel-extra"}),"no partial value");Check(!on(new[]{"--boss-render=RigPixel"}),"exact case");Check(!on(new[]{"--boss-render=rigpixel","--boss-render=sprite"}),"last explicit wins off");Check(on(new[]{"--boss-render=sprite","--boss-render=rigpixel"}),"last explicit wins on");Check(!on(new[]{"--hero-render=rigpixel"}),"hero flag cannot activate boss");Check(!on(new[]{"x--boss-render=rigpixel"}),"no partial key");var role=t.GetMethod("Role");Func<string,string> state=s=>(string)role.Invoke(null,new object[]{s});Check(state("eWalk")=="Walk","core walking uses authored walk");Check(state("bossCharge")=="Hold","charge has no authored clip, no run substitution");foreach(var s in new[]{"bossRmWind","bossSlashWind","bossSlash","bossSlamWind","bossSlam","bossGrabWind","bossGrabLunge","bossGrab","bossDruidDive","bossDruidUnder","bossDruidErupt","bossHeartWind","bossHeartPause","bossRec","eHit","eStagger","eDeath"})Check(state(s)=="Hold","missing action holds idle: "+s);Check(state("idle")=="Idle","v7 authored idle loop");Check(state("eRun")=="Run","run explicitly reports missing v7 clip");Check(state("unknown")=="Hold","unknown safely holds");var palette=t.GetMethod("Palette");foreach(var pair in new[]{new[]{"druid_bone","#b9ad90"},new[]{"druid_bark","#4a3826"},new[]{"druid_feather","#1c2024"},new[]{"druid_hair","#2a2624"},new[]{"druid_beard","#8f8a82"},new[]{"druid_glow","#a8642a"},new[]{"druid_moss","#36421f"},new[]{"staff_bark","#4a3826"},new[]{"staff_leather","#2e231b"},new[]{"staff_bone","#b9ad90"},new[]{"lantern_orb","#a8642a"},new[]{"front_panel_cloth","#26211d"}})Check((string)palette.Invoke(null,new object[]{pair[0]})==pair[1],"LOCK palette "+pair[0]);Check(palette.Invoke(null,new object[]{"iron"})==null,"hero palette cannot leak into boss");}
 Console.WriteLine("druid-rigpixel checks="+checks+" failed="+bad);return bad==0?0:1;}
}
